Here is the commit message:
batman-adv: dat: handle forward allocation error

batadv_dat_forward_data() calls pskb_copy_for_clone() to duplicate an skb
for each DHT candidate, but does not check the return value before passing
it to batadv_send_skb_prepare_unicast_4addr(). That function dereferences
the skb unconditionally, so a failed allocation triggers a NULL pointer
dereference.

Skip forwarding to the current DHT candidate on allocation failure.

Cc: stable@kernel.org
Fixes: 785ea1144182 ("batman-adv: Distributed ARP Table - create DHT helper functions")
Reported-by: Yuan Tan <yuantan098@gmail.com>
Reported-by: Yifan Wu <yifanwucs@gmail.com>
Reported-by: Juefei Pu <tomapufckgml@gmail.com>
Reported-by: Xin Liu <bird@lzu.edu.cn>
Reviewed-by: Yuan Tan <yuantan098@gmail.com>
Signed-off-by: Sven Eckelmann <sven@narfation.org>

Here is the root cause:
Missing NULL check after pskb_copy_for_clone() call in batadv_dat_forward_data(), leading to a NULL pointer dereference when memory allocation fails, because the return value is passed directly to batadv_send_skb_prepare_unicast_4addr() which dereferences the skb without validation.

Here is the patch:
  */
 static bool batadv_dat_forward_data(struct batadv_priv *bat_priv,
 				    struct sk_buff *skb, __be32 ip,
 				    unsigned short vid, int packet_subtype)
 {
 	int i;
 	bool ret = false;
 	int send_status;
 	struct batadv_neigh_node *neigh_node = NULL;
 	struct sk_buff *tmp_skb;
 	struct batadv_dat_candidate *cand;

 	cand = batadv_dat_select_candidates(bat_priv, ip, vid);
 	if (!cand)
 		return ret;

 	batadv_dbg(BATADV_DBG_DAT, bat_priv, "DHT_SEND for %pI4\n", &ip);

 	for (i = 0; i < BATADV_DAT_CANDIDATES_NUM; i++) {
 		if (cand[i].type == BATADV_DAT_CANDIDATE_NOT_FOUND)
 			continue;

 		neigh_node = batadv_orig_router_get(cand[i].orig_node,
 						    BATADV_IF_DEFAULT);
 		if (!neigh_node)
 			goto free_orig;

 		tmp_skb = pskb_copy_for_clone(skb, GFP_ATOMIC);
+		if (!tmp_skb)
+			goto free_neigh;
+
 		if (!batadv_send_skb_prepare_unicast_4addr(bat_priv, tmp_skb,
 							   cand[i].orig_node,
 							   packet_subtype)) {
 			kfree_skb(tmp_skb);
 			goto free_neigh;
 		}

 		send_status = batadv_send_unicast_skb(tmp_skb, neigh_node);
 		if (send_status == NET_XMIT_SUCCESS) {
 			/* count the sent packet */
 			switch (packet_subtype) {
 			case BATADV_P_DAT_DHT_GET:
 				batadv_inc_counter(bat_priv,
 						   BATADV_CNT_DAT_GET_TX);
 				break;
 			case BATADV_P_DAT_DHT_PUT:
 				batadv_inc_counter(bat_priv,
 						   BATADV_CNT_DAT_PUT_TX);
 				break;
 			}

 			/* packet sent to a candidate: return true */
 			ret = true;
 		}
 free_neigh:
 		batadv_neigh_node_put(neigh_node);
 free_orig:
 		batadv_orig_node_put(cand[i].orig_node);
 	}

 	kfree(cand);
 	return ret;
 }



